**Rozwiazanie (C++):**
```cpp
#include <iostream>
#include <fstream>
#include <string>
using namespace std;

string rle(const string& s) {
    string wynik = "";
    int i = 0;
    while (i < (int)s.length()) {
        char c = s[i];
        int cnt = 0;
        while (i < (int)s.length() && s[i] == c) {
            cnt++;
            i++;
        }
        wynik += c;
        wynik += to_string(cnt);
    }
    return wynik;
}

int main() {
    ifstream plik("napisy.txt");
    string s;
    int ile = 0;
    while (plik >> s) {
        string compressed = rle(s);
        int origLen = s.length();
        int compLen = compressed.length();
        cout << s << " -> " << compressed << " (" << origLen << " -> " << compLen << ", ";
        if (compLen < origLen) {
            cout << "kompresja)" << endl;
            ile++;
        } else if (compLen == origLen) {
            cout << "bez zmian)" << endl;
        } else {
            cout << "rozszerzenie)" << endl;
        }
    }
    cout << "Napisy skompresowane (krotszy wynik): " << ile << endl;
    return 0;
}
```

**Wyjasnienie**: RLE grupuje identyczne sasiednie znaki. Wynik jest krotszy gdy sa dlugie serie (np. `aaaaaa` -> `a6`), ale dluzszy gdy znaki sie nie powtarzaja.

Weryfikacja:
- aaabbbcc: a*3, b*3, c*2 -> a3b3c2 (8->6 kompresja)
- abcdefg: kazdy*1 -> a1b1c1d1e1f1g1 (7->14 rozszerzenie)
- aabbccdd: kazdy*2 -> a2b2c2d2 (8->8 bez zmian)
- xxxyyyzzz: kazdy*3 -> x3y3z3 (9->6 kompresja)
- hello: h*1,e*1,l*2,o*1 -> h1e1l2o1 (5->8 rozszerzenie)
- aaaaaa: a*6 -> a6 (6->2 kompresja)
- abababab: kazdy*1 -> a1b1a1b1a1b1a1b1 (8->16 rozszerzenie)
- xyzxyz: kazdy*1 -> x1y1z1x1y1z1 (6->12 rozszerzenie)
Skompresowane: aaabbbcc, xxxyyyzzz, aaaaaa = 3
